import{t as e}from"./types-DccqHlFD.js";var t=`A coupling is a mechanical component used to connect two shafts, pipes, or components together so that power, movement, or fluid can be transferred from one side to another.`,n=`For mechanical applications, a coupling is commonly used to connect two rotating shafts, allowing them to work together while helping to accommodate minor misalignment and reduce vibration.`,r=[`Connecting two shafts in motors, pumps, gearboxes, and machinery`,`Transmitting rotational power from one shaft to another`,`Helping reduce vibration and compensate for slight shaft misalignment`,`Providing easy installation and maintenance between connected components`],i={chain:[`/coupling/chain-coupling/20220901_171113.jpg`,`/coupling/chain-coupling/20220901_171122.jpg`,`/coupling/chain-coupling/20220914_161548.jpg`,`/coupling/chain-coupling/471998801_589373267133832_6784758386205473759_n.jpg`,`/coupling/chain-coupling/472005629_589373440467148_4177432263014128603_n.jpg`,`/coupling/chain-coupling/472481602_592630326808126_8184758270637310791_n.jpg`,`/coupling/chain-coupling/472721308_592630386808120_8487466617108306130_n.jpg`,`/coupling/chain-coupling/473364052_599996739404818_491671725841683162_n.jpg`],fcl:[`/coupling/fcl/20200204_115406.jpg`,`/coupling/fcl/20201006_095037.jpg`,`/coupling/fcl/20201006_095042.jpg`,`/coupling/fcl/WhatsApp-Image-2022-06-11-at-10-07-33-AM-1.jpg`,`/coupling/fcl/WhatsApp-Image-2022-06-11-at-10-07-33-AM.jpg`]};function a(i,a,o=[]){return e({name:i,category:`Couplings`,subtitle:`Coupling`,description:`${t} ${n}`,features:r,specs:{Type:i},imagePath:a,galleryImages:o})}var o=[a(`Chain Coupling`,`/products/coupling/chain-coupling.webp`,i.chain),a(`FCL Coupling`,`/products/coupling/fcl-coupling.webp`,i.fcl),a(`HRC Coupling`,`/products/coupling/hrc-coupling.webp`),a(`Jaw coupling`,`/products/coupling/jaw-coupling.webp`),a(`Tyre Coupling`,`/products/coupling/tyre-coupling.webp`)],s={path:`/coupling`,title:`Coupling`,description:t,productGroups:[{products:o,photos:[]}],photoGroups:[{title:`Chain coupling`,photos:i.chain},{title:`FCL`,photos:i.fcl}],sections:[{kind:`text`,paragraphs:[n]},{kind:`list`,eyebrow:`The used of coupling`,items:r,paragraphs:[`In simple terms: A coupling acts as a connector between two components, allowing them to work together as one system.`]},{kind:`list`,eyebrow:`Applications of coupling`,intro:`The applications of coupling depend on the field you are studying. In physics and engineering, coupling generally means transferring energy, force, or signals between two systems.`,items:[`Mechanical engineering – Connects two shafts to transmit power from one shaft to another, such as in motors and gearboxes.`,`Electrical engineering – Transfers electrical signals or energy between circuits, such as transformer coupling.`,`Communication systems – Transfers signals between electronic components, antennas, and transmission lines.`,`Optical communication – Transfers light from one optical fiber or device to another.`,`Automobiles – Connects the engine to the transmission system to transfer rotational power.`,`Chemical engineering – Coupling reactions join two molecules to form a larger molecule.`,`Medical equipment – Ultrasound coupling gel helps transmit sound waves between the transducer and the skin.`,`Robotics – Connects mechanical components and transfers motion or force between parts.`]}]};export{o as n,s as t};